for (const item of items) {
  // تطبيق دالة trim لإزالة المساحات البيضاء من scientificName
  if (item.json.scientificName) {
    item.json.scientificName = item.json.scientificName.trim();
  }

  // تطبيق دالة trim لإزالة المساحات البيضاء من City
  if (item.json.City) {
    item.json.City = item.json.City.trim();
  }

  // يجب عليك أيضًا تطبيق تغيير حالة الأحرف (Case) على المدينة
  // لكي تتوافق مع معايير تنظيف البيانات (Paris بدلاً من paris).
  if (item.json.City) {
    item.json.City = item.json.City.charAt(0).toUpperCase() + item.json.City.slice(1);
  }
}

return items;

for (const item of items) {
  if (item.json.scientificName) {
    // 1. استخدام المسافة (' ') كفاصل (Separator)
    const nameParts = item.json.scientificName.split(' ');

    // 2. تعيين الجزء الأول كـ Genus (الجنس)
    item.json.Genus = nameParts[0];

    // 3. تعيين الجزء الثاني كـ Species (النوع)
    // نحن هنا نجمع الجزأين الثاني والثالث للمثال (lupus familiaris)
    // إذا كان الاسم ثلاثياً (ثلاث كلمات):
    item.json.Species = nameParts.slice(1).join(' '); 

    // 4. (اختياري) إزالة العمود الأصلي 
    // delete item.json.scientificName;
  }
}

return items;

for (const item of items) {
  if (item.json.price) {
    let priceValue = String(item.json.price);

    // 1. (Optionnel) Nettoyer l'espace blanc au cas où il y en aurait
    priceValue = priceValue.trim();

    // 2. Étape de NETTOYAGE : Supprimer tous les caractères qui ne sont 
    // pas des chiffres (0-9) ou un point (.), comme les symboles de devise ($ ou €) 
    // ou les séparateurs de milliers (,).
    // Exemple: Si priceValue était "$1,200.50", il devient "1200.50"
    priceValue = priceValue.replace(/[^0-9.]/g, ''); 

    // 3. Étape de CONVERSION : Transformer la chaîne de caractères propre 
    // en un nombre à virgule flottante (nombre décimal).
    item.json.price_cleaned = parseFloat(priceValue);

    // 4. (Optionnel) Supprimer l'ancienne colonne 'price' si vous n'en avez plus besoin
    // delete item.json.price;
  }
}

return items;
